require_once __DIR__.'/includes/student_auth_check.php'; require_once __DIR__.'/config/db.php'; $id=filter_input(INPUT_GET,'booking_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:filter_input(INPUT_POST,'booking_id',FILTER_VALIDATE_INT);$booking=null;$error='';
try{$pdo=db();$q=$pdo->prepare('SELECT b.*,u.full_name tutor_name,s.name subject FROM bookings b JOIN tutors t ON t.id=b.tutor_id JOIN users u ON u.id=t.user_id JOIN subjects s ON s.id=b.subject_id WHERE b.id=:id AND b.student_id=:student');$q->execute(['id'=>$id,'student'=>$_SESSION['user_id']]);$booking=$q->fetch();}catch(Throwable $e){}
if(!$booking){http_response_code(404);exit('Booking not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){$method=$_POST['method']??'';if(!verify_csrf($_POST['csrf_token']??null)||!in_array($method,['bkash','nagad','rocket','visa','mastercard'],true))$error='Choose a valid payment method.';else try{$q=$pdo->prepare("INSERT INTO payments(booking_id,student_id,amount,method,transaction_id,status) VALUES(:booking,:student,:amount,:method,:transaction,'success')");$q->execute(['booking'=>$id,'student'=>$_SESSION['user_id'],'amount'=>$booking['price'],'method'=>$method,'transaction'=>'MOCK-'.strtoupper(bin2hex(random_bytes(5)))]);$q=$pdo->prepare("INSERT INTO notifications(user_id,type,message,related_id) VALUES(:user,'payment_success','Your payment was successful.',:booking)");$q->execute(['user'=>$_SESSION['user_id'],'booking'=>$id]);header('Location: payment-success.php?booking_id='.$id);exit;}catch(Throwable $e){$error='Payment could not be recorded. It may already have been paid.';}}
$pageTitle='Payment';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="section-soft py-5"><div class="container" style="max-width:850px"><div class="row g-4"><div class="col-md-7"><div class="booking-card"><h1 class="h3">Choose payment method</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$id?>"><div class="row g-2 mb-3"><?php foreach(['bkash'=>'bKash','nagad'=>'Nagad','rocket'=>'Rocket','visa'=>'Visa','mastercard'=>'Mastercard'] as $key=>$label):?><div class="col-6"><input class="btn-check" type="radio" name="method" id="<?=$key?>" value="<?=$key?>" required><label class="btn btn-outline-brand w-100 payment-method <?=$key?>" for="<?=$key?>"><?=$label?></label></div><?php endforeach;?></div><div id="mobileFields"><label class="form-label">Mobile number</label><input class="form-control mb-2" type="tel" placeholder="01XXXXXXXXX"><label class="form-label">PIN</label><input class="form-control" type="password" placeholder="PIN (mock only)"></div><div id="cardFields" class="d-none"><label class="form-label">Card number</label><input class="form-control mb-2" inputmode="numeric" pattern="[0-9 ]{13,19}" placeholder="1234 5678 9012 3456"><div class="row"><div class="col"><input class="form-control" placeholder="MM/YY"></div><div class="col"><input class="form-control" inputmode="numeric" placeholder="CVV"></div></div></div><button class="btn btn-brand w-100 mt-4">Confirm payment</button></form></div></div><div class="col-md-5"><div class="booking-summary"><h2 class="h5">Payment summary</h2><p class="mb-1"><?=e($booking['subject'])?> with <?=e($booking['tutor_name'])?></p><p class="small text-secondary"><?=e($booking['booking_date'])?> · <?=date('g:i A',strtotime($booking['start_time']))?></p><hr><div class="d-flex justify-content-between"><span>Session fee</span><strong>৳<?=number_format((float)$booking['price'])?></strong></div><div class="d-flex justify-content-between"><span>Platform fee</span><span>৳0</span></div><hr><div class="d-flex justify-content-between"><strong>Total</strong><strong>৳<?=number_format((float)$booking['price'])?></strong></div></div></div></div></div></main><script>const cards=document.querySelector('#cardFields'),mobile=document.querySelector('#mobileFields');document.querySelectorAll('[name=method]').forEach(x=>x.onchange=()=>{let c=['visa','mastercard'].includes(x.value);cards.classList.toggle('d-none',!c);mobile.classList.toggle('d-none',c)})</script><?php require __DIR__.'/includes/footer.php';?>
